"""Validated holiday dates, stored as merged ranges of calendar ordinals."""

import datetime as dt
import re
from bisect import bisect_left

from .errors import PlanError
from .rules import DATE

_ENTRY = re.compile(rf"({DATE})(?:\.\.({DATE}))?")


class Holidays:
    def __init__(self, entries):
        if not isinstance(entries, list):
            raise PlanError("holidays must be a list")
        ranges = []
        for index, entry in enumerate(entries, 1):
            match = _ENTRY.fullmatch(entry) if isinstance(entry, str) else None
            if match is None:
                raise PlanError(f"holiday #{index} must be a date or inclusive date range")
            first, last = match.groups()
            try:
                start = dt.date.fromisoformat(first).toordinal()
                end = dt.date.fromisoformat(last or first).toordinal()
            except ValueError:
                raise PlanError(f"holiday #{index} has an invalid date") from None
            if end < start:
                raise PlanError(f"holiday #{index} ends before it starts")
            ranges.append((start, end))

        self.ranges = []
        for start, end in sorted(ranges):
            if self.ranges and start <= self.ranges[-1][1] + 1:
                previous_start, previous_end = self.ranges[-1]
                self.ranges[-1] = (previous_start, max(previous_end, end))
            else:
                self.ranges.append((start, end))
        self.ends = [end for _, end in self.ranges]

    def __bool__(self):
        return bool(self.ranges)

    def containing(self, day):
        index = bisect_left(self.ends, day)
        if index < len(self.ranges) and self.ranges[index][0] <= day:
            return self.ranges[index]
        return None

    def intersecting(self, first, last):
        index = bisect_left(self.ends, first)
        while index < len(self.ranges) and self.ranges[index][0] <= last:
            yield self.ranges[index]
            index += 1
"""Turn one rule into concrete occurrences (SPEC.md sections 3 and 4)."""

import calendar
import datetime as dt
from dataclasses import dataclass
from math import gcd
from typing import TYPE_CHECKING

from .errors import PlanError
from .rules import ELAPSED_SECONDS

if TYPE_CHECKING:
    from .plan import RuleDef

SECONDS_PER_DAY = 86400
LAST_ORDINAL = dt.date.max.toordinal()
UTC = dt.timezone.utc


@dataclass
class Occurrence:
    rule: "RuleDef"
    key: str
    start: int
    end: int


def instant(aware):
    """Return whole seconds since 0001-01-01T00:00:00Z."""
    wall = ((aware.toordinal() - 1) * SECONDS_PER_DAY +
            aware.hour * 3600 + aware.minute * 60 + aware.second)
    return wall - int(aware.utcoffset().total_seconds())


def local_instant(local, zone):
    # fold=0 selects the earlier instant in a fold and the pre-gap offset in a gap.
    # Applying the pre-gap offset gives the same instant as shifting past the gap.
    return instant(local.replace(tzinfo=zone, fold=0))


def _wall_datetime(seconds):
    days, seconds = divmod(seconds, SECONDS_PER_DAY)
    date = dt.date.fromordinal(days + 1)
    return dt.datetime.combine(date, dt.time()) + dt.timedelta(seconds=seconds)


def _local_datetime(seconds, zone):
    # A local date at either calendar limit can have a UTC date outside it.
    # Use the offset at the nearest representable UTC instant in that case.
    utc_seconds = max(0, min(seconds, LAST_ORDINAL * SECONDS_PER_DAY - 1))
    local = _wall_datetime(utc_seconds).replace(tzinfo=UTC).astimezone(zone)
    if utc_seconds != seconds:
        local = local + dt.timedelta(seconds=seconds - utc_seconds)
    return local


def format_instant(seconds, zone):
    local = _local_datetime(seconds, zone)
    # Some historical offsets include seconds. Output uses minute precision.
    return local.isoformat(timespec="seconds")[:25]


def _periods(anchor, first, last, stride):
    first += (anchor - first) % stride
    return range(first, last + 1, stride)


def _month_index(day):
    return (day.year - 1) * 12 + day.month - 1


def _candidate_dates(rule, lo, hi):
    anchor = rule.start.toordinal()
    lo = max(lo, anchor)
    if rule.until is not None:
        hi = min(hi, rule.until.toordinal())
    if lo > hi:
        return

    if rule.unit == "day":
        for day in _periods(anchor, lo, hi, rule.every):
            yield dt.date.fromordinal(day)
    elif rule.unit == "week":
        week_zero = anchor - rule.start.weekday()
        first_monday = lo - dt.date.fromordinal(lo).weekday()
        for monday in _periods(week_zero, first_monday, hi, rule.every * 7):
            for weekday in rule.on:
                if lo <= monday + weekday <= hi:
                    yield dt.date.fromordinal(monday + weekday)
    else:
        first, last = dt.date.fromordinal(lo), dt.date.fromordinal(hi)
        # A repeated calendar cycle with no valid dates can never yield a date,
        # even if a counted rule is queried much later.
        cycle = 4800 if rule.on[0] == 29 else 12
        cycle_steps = cycle // gcd(cycle, rule.every)
        skipped = 0
        for month_index in _periods(_month_index(rule.start), _month_index(first),
                                    _month_index(last), rule.every):
            year, month = divmod(month_index, 12)
            year, month = year + 1, month + 1
            month_len = calendar.monthrange(year, month)[1]
            days = {month_len if item == "last" else item for item in rule.on
                    if item == "last" or item <= month_len}
            if not days:
                skipped += 1
                if skipped == cycle_steps:
                    return
                continue
            skipped = 0
            for day in sorted(days):
                date = dt.date(year, month, day)
                if first <= date <= last:
                    yield date


def _calendar_candidates(ruledef, first, last):
    for date in _candidate_dates(ruledef.rule, first, last):
        seen = set()
        for time in ruledef.rule.at:
            start = local_instant(dt.datetime.combine(date, time), ruledef.tz)
            if start not in seen:
                seen.add(start)
                yield date, time, start


def _shifted_candidates(ruledef, block_start, block_end, first, last):
    destination = block_end + 1
    if destination > LAST_ORDINAL:
        return
    occupied = {time for _, time, _ in _calendar_candidates(ruledef, destination, destination)}
    if len(occupied) == len(ruledef.rule.at):
        return

    target = dt.date.fromordinal(destination)
    # The earliest surviving key in the whole block wins each wall time, even
    # when an override check asks for keys from only part of that block.
    for date, time, _ in _calendar_candidates(ruledef, block_start, min(block_end, last)):
        if time not in occupied:
            occupied.add(time)
            if date.toordinal() >= first:
                start = local_instant(dt.datetime.combine(target, time), ruledef.tz)
                yield date, time, start
            if len(occupied) == len(ruledef.rule.at):
                return


def _calendar_after_holidays(ruledef, holidays, first, last):
    if ruledef.holiday == "keep":
        yield from _calendar_candidates(ruledef, first, last)
        return

    cursor = first
    for block_start, block_end in holidays.intersecting(first, last):
        yield from _calendar_candidates(ruledef, cursor, block_start - 1)
        if ruledef.holiday == "shift":
            yield from _shifted_candidates(ruledef, block_start, block_end, first, last)
        cursor = block_end + 1
    yield from _calendar_candidates(ruledef, cursor, last)


def expand_calendar(ruledef, holidays, first, last):
    """Yield retained pairs for keys with nominal date ordinals in [first, last]."""
    rule = ruledef.rule
    scan_from = rule.start.toordinal() if rule.times is not None else first
    candidates = _calendar_after_holidays(ruledef, holidays, scan_from, last)
    for count, (date, time, start) in enumerate(candidates, 1):
        if date.toordinal() >= first:
            key = dt.datetime.combine(date, time).isoformat(timespec="minutes")
            yield key, start
        if count == rule.times:
            return


def expand_elapsed(ruledef, holidays, first, last):
    """Yield retained pairs for starts in the inclusive instant range."""
    rule = ruledef.rule
    anchor = local_instant(dt.datetime.combine(rule.start, rule.anchor_time), ruledef.tz)
    step = rule.every * ELAPSED_SECONDS[rule.unit]
    skip = ruledef.holiday == "skip" and bool(holidays)
    until = rule.until.toordinal() if rule.until is not None else None
    if until is not None:
        # Even the most negative UTC offset is less than one day in magnitude.
        last = min(last, (until + 1) * SECONDS_PER_DAY - 1)

    scan_from = max(anchor, first)
    if rule.times is not None:
        if skip:
            scan_from = anchor
        else:
            last = min(last, anchor + (rule.times - 1) * step)

    start = scan_from + (anchor - scan_from) % step
    count = 0
    while start <= last:
        if skip or until is not None:
            try:
                day = _local_datetime(start, ruledef.tz).date().toordinal()
            except (ValueError, OverflowError):
                raise PlanError(f"rule {ruledef.id}: timestamp outside the supported calendar") from None
            if until is not None and day > until:
                start += step
                continue
            block = holidays.containing(day) if skip else None
            if block is not None:
                # Check the edges individually because the UTC offset can
                # change. Well inside the block every start is on a holiday.
                safe_start = block[0] * SECONDS_PER_DAY
                safe_end = (block[1] - 1) * SECONDS_PER_DAY
                if safe_start <= start < safe_end:
                    start = safe_end + (anchor - safe_end) % step
                else:
                    start += step
                continue

        if start >= first:
            try:
                key = _wall_datetime(start).isoformat(timespec="minutes") + "Z"
            except (ValueError, OverflowError):
                raise PlanError(f"rule {ruledef.id}: UTC key outside the supported calendar") from None
            yield key, start
        count += 1
        if count == rule.times:
            return
        start += step


def expand(ruledef, holidays, first, last):
    """Yield retained pairs whose starts are in the inclusive instant range."""
    if ruledef.rule.elapsed:
        yield from expand_elapsed(ruledef, holidays, first, last)
        return

    # The wall date for a start can differ from its UTC date by one day.
    first_day = max(1, first // SECONDS_PER_DAY)
    last_day = min(LAST_ORDINAL, last // SECONDS_PER_DAY + 2)
    if first_day > last_day:
        return
    if ruledef.holiday == "shift":
        # A holiday block may contribute starts on the first day in range
        # even when the block's original keys are much earlier.
        block = holidays.containing(first_day - 1)
        if block is not None:
            first_day = block[0]
    for key, start in expand_calendar(ruledef, holidays, first_day, last_day):
        if first <= start <= last:
            yield key, start
"""Plan loading (SPEC.md sections 1 and 5)."""

import datetime as dt
import re
from dataclasses import dataclass
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from .errors import PlanError, RuleSyntaxError
from .expand import UTC, expand_calendar, expand_elapsed, instant, local_instant
from .holidays import Holidays
from .rules import DATE, LOCAL_MINUTE, UTC_MINUTE, Rule, parse_duration, parse_rule


@dataclass
class RuleDef:
    index: int
    id: str
    rule: Rule
    tz: ZoneInfo
    priority: int
    holiday: str


@dataclass
class Override:
    start: int = None          # None means cancel
    minutes: int = None


@dataclass
class Plan:
    rules: list
    overrides: dict           # rule id -> {key: Override}
    min_segment: int
    holidays: Holidays


def _zone(name, prefix=""):
    if not isinstance(name, str):
        raise PlanError(f"{prefix}timezone must be a string")
    # Some installations also expose system files and alternate TZif trees.
    if name in ("localtime", "posixrules") or name.startswith(("posix/", "right/")):
        raise PlanError(f"{prefix}unknown timezone {name!r}")
    try:
        return ZoneInfo(name)
    except (ValueError, ZoneInfoNotFoundError):
        raise PlanError(f"{prefix}unknown timezone {name!r}") from None


def _load_rules(items, default_tz):
    if not isinstance(items, list):
        raise PlanError("rules must be a list")
    rules = {}
    for index, item in enumerate(items):
        if not isinstance(item, dict):
            raise PlanError(f"rule #{index + 1} must be an object")
        rid = item.get("id")
        if not isinstance(rid, str):
            raise PlanError(f"rule #{index + 1} must have a string id")
        if not re.fullmatch(r"[A-Za-z0-9_-]+", rid):
            raise PlanError(f"invalid rule id {rid!r} at rule #{index + 1}")
        if rid in rules:
            raise PlanError(f"rule {rid}: duplicate id")
        if not isinstance(item.get("rule"), str):
            raise PlanError(f"rule {rid}: rule text must be a string")
        try:
            rule = parse_rule(item["rule"])
        except RuleSyntaxError as exc:
            raise RuleSyntaxError(f"rule {rid}: {exc}", exc.position, exc.text) from exc
        tz = _zone(item["timezone"], f"rule {rid}: ") if "timezone" in item else default_tz
        priority = item.get("priority", 0)
        if not isinstance(priority, int) or isinstance(priority, bool):
            raise PlanError(f"rule {rid}: priority must be an integer")
        holiday = item.get("holiday", "keep")
        if holiday not in ("keep", "skip", "shift"):
            raise PlanError(f"rule {rid}: holiday must be keep, skip, or shift")
        if rule.elapsed and holiday == "shift":
            raise PlanError(f"rule {rid}: minute and hour rules cannot shift holidays")
        rules[rid] = RuleDef(index, rid, rule, tz, priority, holiday)
    return rules


def _override_key(ruledef, value):
    if not isinstance(value, str):
        raise PlanError(f"rule {ruledef.id}: override key must be a string")
    try:
        if ruledef.rule.elapsed:
            if UTC_MINUTE.fullmatch(value):
                utc = dt.datetime.fromisoformat(value[:-1]).replace(tzinfo=UTC)
                return value, instant(utc)
        else:
            if len(ruledef.rule.at) == 1 and re.fullmatch(DATE, value):
                value += "T" + ruledef.rule.at[0].isoformat(timespec="minutes")
            if LOCAL_MINUTE.fullmatch(value):
                return value, dt.date.fromisoformat(value[:10]).toordinal()
    except ValueError:
        pass
    raise PlanError(f"rule {ruledef.id}: invalid override key {value!r}")


def _move(ruledef, item):
    value = item.get("to")
    if not isinstance(value, str) or not LOCAL_MINUTE.fullmatch(value):
        raise PlanError(f"rule {ruledef.id}: move override needs a valid 'to'")
    try:
        local = dt.datetime.fromisoformat(value)
    except ValueError:
        raise PlanError(f"rule {ruledef.id}: move override needs a valid 'to'") from None
    minutes = None
    if "for" in item:
        minutes = parse_duration(item["for"])
        if minutes is None:
            raise PlanError(f"rule {ruledef.id}: invalid move duration")
    return Override(local_instant(local, ruledef.tz), minutes)


def _validate_keys(ruledef, holidays, positions):
    if ruledef.rule.elapsed:
        expand_keys, width = expand_elapsed, 59
    else:
        expand_keys, width = expand_calendar, 0
    direct_count = ruledef.rule.elapsed and (ruledef.holiday == "keep" or not holidays)
    if ruledef.rule.times is None or direct_count:
        for key, position in positions.items():
            candidates = expand_keys(ruledef, holidays, position, position + width)
            if not any(candidate == key for candidate, _ in candidates):
                raise PlanError(f"rule {ruledef.id}: override key {key!r} has no occurrence")
    else:
        remaining = set(positions)
        first, last = min(positions.values()), max(positions.values()) + width
        for key, _ in expand_keys(ruledef, holidays, first, last):
            remaining.discard(key)
            if not remaining:
                return
        key = min(remaining)
        raise PlanError(f"rule {ruledef.id}: override key {key!r} has no occurrence")


def _load_overrides(items, rules, holidays):
    if not isinstance(items, list):
        raise PlanError("overrides must be a list")
    overrides = {}
    positions = {}
    for item in items:
        if not isinstance(item, dict):
            raise PlanError("override must be an object")
        rid = item.get("rule")
        if not isinstance(rid, str):
            raise PlanError("override must name a rule")
        if rid not in rules:
            raise PlanError(f"override for unknown rule {rid!r}")
        ruledef = rules[rid]
        key, position = _override_key(ruledef, item.get("key"))
        by_key = overrides.setdefault(rid, {})
        if key in by_key:
            raise PlanError(f"rule {rid}: duplicate override for {key!r}")
        action = item.get("action")
        if action == "cancel":
            by_key[key] = Override()
        elif action == "move":
            by_key[key] = _move(ruledef, item)
        else:
            raise PlanError(f"rule {rid}: override action must be cancel or move")
        positions.setdefault(rid, {})[key] = position
    for rid, keys in positions.items():
        _validate_keys(rules[rid], holidays, keys)
    return overrides


def load_plan(raw):
    if not isinstance(raw, dict):
        raise PlanError("plan must be an object")
    if "timezone" not in raw:
        raise PlanError("plan has no timezone")
    default_tz = _zone(raw["timezone"])
    rules = _load_rules(raw.get("rules"), default_tz)
    holidays = Holidays(raw.get("holidays", []))
    overrides = _load_overrides(raw.get("overrides", []), rules, holidays)
    min_segment = 0
    if "min_segment" in raw:
        min_segment = parse_duration(raw["min_segment"])
        if min_segment is None:
            raise PlanError("invalid min_segment duration")
    return Plan(list(rules.values()), overrides, min_segment, holidays)

"""Rule text parsing (SPEC.md section 2)."""

import datetime as dt
import re
from dataclasses import dataclass, field
from decimal import Decimal

from .errors import RuleSyntaxError

WEEKDAYS = ["mon", "tue", "wed", "thu", "fri", "sat", "sun"]
ELAPSED_SECONDS = {"minute": 60, "hour": 3600}
UNITS = {form: unit for unit in ("day", "week", "month", *ELAPSED_SECONDS)
         for form in (unit, unit + "s")}
DATE = r"[0-9]{4}-[0-9]{2}-[0-9]{2}"
CLOCK = r"(?:[01][0-9]|2[0-3]):[0-5][0-9]"
LOCAL_MINUTE = re.compile(DATE + "T" + CLOCK)
UTC_MINUTE = re.compile(LOCAL_MINUTE.pattern + "Z")
_POSITIVE = re.compile(r"[1-9][0-9]*")
_DURATION = re.compile(r"(?:(?P<days>[1-9][0-9]*)d)?"
                       r"(?:(?P<hours>[1-9][0-9]*)h)?"
                       r"(?:(?P<minutes>[1-9][0-9]*)m)?", re.IGNORECASE | re.ASCII)


@dataclass
class Rule:
    every: int = 1
    unit: str = "day"
    on: list = field(default_factory=list)   # weekday indexes, or month days / "last"
    at: list = field(default_factory=list)   # datetime.time
    minutes: int = 0
    start: dt.date = None
    anchor_time: dt.time = None
    until: dt.date = None
    times: int = None

    @property
    def elapsed(self):
        return self.unit in ELAPSED_SECONDS


def decimal_int(text):
    try:
        return int(text)
    except ValueError:
        # The grammar has no upper bound on the number of digits.
        return int(Decimal(text))


def _decimal_text(number):
    try:
        return str(number)
    except ValueError:
        return format(Decimal(number), "f")


def parse_duration(word):
    """'1h30m' -> 90. Returns None when the word is not a duration."""
    match = _DURATION.fullmatch(word) if isinstance(word, str) and word else None
    if match is None:
        return None
    days, hours, minutes = (decimal_int(part or "0") for part in match.groups())
    return days * 1440 + hours * 60 + minutes


def format_duration(minutes):
    days, minutes = divmod(minutes, 1440)
    hours, minutes = divmod(minutes, 60)
    return "".join(_decimal_text(value) + unit
                   for value, unit in ((days, "d"), (hours, "h"), (minutes, "m"))
                   if value)


def _count(word):
    return decimal_int(word) if _POSITIVE.fullmatch(word) else None


def _time(word):
    return dt.time.fromisoformat(word) if re.fullmatch(CLOCK, word) else None


def _date(word):
    return dt.date.fromisoformat(word) if re.fullmatch(DATE, word) else None


def _local_minute(word):
    word = word.upper()
    return dt.datetime.fromisoformat(word) if LOCAL_MINUTE.fullmatch(word) else None


def _month_day(word):
    if word == "last":
        return word
    return int(word) if re.fullmatch(r"[1-9]|[12][0-9]|3[01]", word) else None


def _sorted_list(word, parse_item, sort_key=None):
    items = [parse_item(part) for part in word.split(",")]
    if None in items or len(set(items)) != len(items):
        return None
    return sorted(items, key=sort_key)


class _Words:
    def __init__(self, text):
        self.text = text
        self.tokens = [(m.group().lower(), m.start()) for m in re.finditer(r"[^ \t]+", text)]
        self.index = 0

    def peek(self):
        return self.tokens[self.index][0] if self.index < len(self.tokens) else None

    def fail(self, message):
        position = self.tokens[self.index][1] if self.index < len(self.tokens) else len(self.text)
        raise RuleSyntaxError(message, position, self.text)

    def expect(self, keyword):
        if self.peek() != keyword:
            self.fail(f"expected '{keyword}'")
        self.index += 1

    def convert(self, what, parse):
        word = self.peek()
        if word is None:
            self.fail(f"expected {what}, found end of rule")
        try:
            value = parse(word)
        except ValueError:
            value = None
        if value is None:
            self.fail(f"expected {what}, found {word!r}")
        self.index += 1
        return value


def parse_rule(text):
    if not isinstance(text, str):
        raise RuleSyntaxError("rule text must be a string", 0)
    w = _Words(text)
    rule = Rule()
    w.expect("every")
    if w.peek() is not None and re.fullmatch(r"[0-9]+", w.peek()):
        rule.every = w.convert("a count", _count)
    rule.unit = w.convert("a unit", UNITS.get)

    if w.peek() == "on" and rule.unit in ("week", "month"):
        w.expect("on")
        if rule.unit == "week":
            rule.on = w.convert("weekdays", lambda s: _sorted_list(s, WEEKDAYS.index))
        else:
            rule.on = w.convert("month days", lambda s: _sorted_list(
                s, _month_day, lambda day: 32 if day == "last" else day))
    if not rule.elapsed:
        w.expect("at")
        rule.at = w.convert("times", lambda s: _sorted_list(s, _time))
    w.expect("for")
    rule.minutes = w.convert("a duration", parse_duration)
    w.expect("from")
    if rule.elapsed:
        anchor = w.convert("a local date-time", _local_minute)
        rule.start, rule.anchor_time = anchor.date(), anchor.time()
    else:
        rule.start = w.convert("a date", _date)

    if w.peek() == "until":
        w.expect("until")

        def end_date(word):
            date = _date(word)
            return date if date is not None and date >= rule.start else None

        rule.until = w.convert("a date on or after the start date", end_date)
    elif w.peek() == "times":
        w.expect("times")
        rule.times = w.convert("a count", _count)
    if w.peek() is not None:
        w.fail(f"unexpected token {w.peek()!r}")

    if not rule.on:
        if rule.unit == "week":
            rule.on = [rule.start.weekday()]
        elif rule.unit == "month":
            rule.on = [rule.start.day]
    return rule


def canonical(text):
    rule = parse_rule(text)
    unit = rule.unit if rule.every == 1 else rule.unit + "s"
    out = ["every", _decimal_text(rule.every), unit]
    if rule.unit == "week":
        out += ["on", ",".join(WEEKDAYS[d] for d in rule.on)]
    elif rule.unit == "month":
        out += ["on", ",".join(str(d) for d in rule.on)]
    if rule.elapsed:
        start = dt.datetime.combine(rule.start, rule.anchor_time).isoformat(timespec="minutes")
    else:
        out += ["at", ",".join(t.isoformat(timespec="minutes") for t in rule.at)]
        start = rule.start.isoformat()
    out += ["for", format_duration(rule.minutes), "from", start]
    if rule.until is not None:
        out += ["until", rule.until.isoformat()]
    if rule.times is not None:
        out += ["times", _decimal_text(rule.times)]
    return " ".join(out)
"""Queries over a plan (SPEC.md sections 6 and 7)."""

import datetime as dt
import re
from heapq import heappop, heappush
from operator import attrgetter

